CREATE TABLE IF NOT EXISTS order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), product_name TEXT NOT NULL, quantity NUMERIC(10,2) NOT NULL CHECK (quantity > 0), unit TEXT NOT NULL, price_at_purchase NUMERIC(10,2) NOT NULL, subtotal NUMERIC(10,2) NOT NULL);
